1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"net/http"
10		"sort"
11		"strings"
12		"time"
13	
14		"charm.land/lipgloss/v2"
15		"github.com/entireio/cli/cmd/entire/cli/api"
16		"github.com/entireio/cli/cmd/entire/cli/auth"
17		"github.com/spf13/cobra"
18	)
19	
20	// authTokenLister lists API tokens for the authenticated user. The
21	// implementation resolves its own data-API bearer via
22	// auth.TokenForResource (RFC 8693 exchange in split-host setups, same-
23	// host shortcut otherwise); callers don't pass a bearer through, which
24	// removes the temptation to forward the wrong-audience keyring token.
25	type authTokenLister func(ctx context.Context) ([]api.Token, error)
26	
27	// authTokenRevoker revokes a single API token by id. Same bearer-
28	// resolution contract as authTokenLister.
29	type authTokenRevoker func(ctx context.Context, id string) error
30	
31	// User-visible placeholder strings. Promoted to constants so tests and
32	// production share a single source of truth.
33	const (
34		placeholderDash = "-"
35		lastUsedNever   = "never"
36		lastUsedJustNow = "just now"
37	)
38	
39	// requireSecureBaseURL enforces TLS unless insecureHTTPAuth is set. Every
40	// command that sends a bearer token over the network (login, logout,
41	// auth status/list/revoke) must call this so credentials don't leak over
42	// plaintext HTTP without explicit opt-in.
43	//
44	// Both the auth and data API origins are checked: the bearer travels to the
45	// auth host for login + auth-token management, and to the data host for
46	// search/activity/dispatch/etc. When both origins resolve to the same host
47	// (e.g. an explicitly collapsed single-host deployment) the redundant second
48	// parse is skipped.
49	//
50	// When the opt-in flag is set, the tokenmanager's matching HTTP guard is
51	// also relaxed via auth.EnableInsecureHTTP — otherwise an STS exchange
52	// against a private-network http:// auth host would fail at the
53	// tokenmanager layer even though the per-command TLS check was waived.
54	func requireSecureBaseURL(insecureHTTPAuth bool) error {
55		if insecureHTTPAuth {
56			auth.EnableInsecureHTTP()
57			return nil
58		}
59		dataURL, authURL := api.BaseURL(), api.AuthBaseURL()
60		if err := api.RequireSecureURL(dataURL); err != nil {
61			return fmt.Errorf("base URL check: %w", err)
62		}
63		if authURL == dataURL {
64			return nil
65		}
66		if err := api.RequireSecureURL(authURL); err != nil {
67			return fmt.Errorf("auth base URL check: %w", err)
68		}
69		return nil
70	}
71	
72	// newAPITokensClient builds an api.Client for the auth-token management
73	// endpoints (list / revoke / current). API tokens live on the data API
74	// regardless of split-host config — the auth host (entire-core in v2)
75	// mints OAuth tokens but doesn't host application API token management
76	// endpoints — so this targets api.BaseURL().
77	//
78	// The supplied token must already be scoped for api.BaseURL(). Callers
79	// must obtain it via resolveDataAPIToken (or auth.TokenForResource
80	// directly) rather than handing through the raw keyring entry — the
81	// keyring stores the auth-host-issued core token, which the data API
82	// rejects in split-host setups.
83	func newAPITokensClient(token string) *api.Client {
84		return api.NewClientWithBaseURL(token, api.BaseURL()).
85			WithAuthTokensPath(auth.CurrentProvider().AuthTokensPath)
86	}
87	
88	// resolveDataAPIToken returns a bearer scoped for the data API. In
89	// split-host setups this triggers an RFC 8693 exchange against the
90	// auth host's STS endpoint; in single-host setups the tokenmanager
91	// hits the same-host shortcut and returns the core token unchanged.
92	// Centralised so the audience-mismatch bug that motivated this fix
93	// can't be reintroduced piecemeal at individual call sites.
94	func resolveDataAPIToken(ctx context.Context) (string, error) {
95		token, err := auth.TokenForResource(ctx, api.OriginOnly(api.BaseURL()))
96		if err != nil {
97			return "", fmt.Errorf("resolve API token: %w", err)
98		}
99		return token, nil
100	}
101	
102	// isKeychainTokenRejected reports whether err indicates the stored
103	// keyring token can't authenticate against the data API. Three failure
104	// modes collapse into this single "the user must re-login" branch:
105	//
106	//   - data API returned 401 (single-host, or after a successful STS
107	//     exchange whose result the data API then rejected),
108	//   - tokenmanager's preflight rejected an expired core token JWT
109	//     (surfacing as auth.ErrNotLoggedIn even though the keyring entry
110	//     is still present),
111	//   - the STS endpoint rejected the core token during exchange in a
112	//     split-host setup. auth-go's sts package returns the response as
113	//     "token exchange: status 4xx: <code>[: <desc>]" with no typed
114	//     sentinel exposed, so detection has to be by prefix. The "status
115	//     4" anchor catches the entire 4xx range — every 4xx from STS is
116	//     a credential problem, none are retryable without user action.
117	//
118	// Other shapes (network errors, malformed STS response, manager
119	// construction failures) deliberately don't match — the user sees the
120	// real diagnostic instead of a misleading "re-login" hint.
121	func isKeychainTokenRejected(err error) bool {
122		if api.IsHTTPErrorStatus(err, http.StatusUnauthorized) {
123			return true
124		}
125		if errors.Is(err, auth.ErrNotLoggedIn) {
126			return true
127		}
128		return strings.Contains(err.Error(), "token exchange: status 4")
129	}
130	
131	// addInsecureHTTPAuthFlag attaches the hidden --insecure-http-auth flag used
132	// by every authenticated command for local development.
133	func addInsecureHTTPAuthFlag(cmd *cobra.Command, target *bool) {
134		cmd.Flags().BoolVar(target, "insecure-http-auth", false, "Allow authentication over plain HTTP (insecure, for local development only)")
135		if err := cmd.Flags().MarkHidden("insecure-http-auth"); err != nil {
136			panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
137		}
138	}
139	
140	func newAuthCmd() *cobra.Command {
141		cmd := &cobra.Command{
142			Use:   "auth",
143			Short: "Manage authentication and API tokens",
144			Long:  "Authentication subcommands. Includes login, logout, status, listing tokens, and revoking tokens.",
145			RunE: func(cmd *cobra.Command, _ []string) error {
146				return cmd.Help()
147			},
148		}
149	
150		cmd.AddCommand(newLoginCmd())
151		cmd.AddCommand(newLogoutCmd())
152		cmd.AddCommand(newAuthStatusCmd())
153		cmd.AddCommand(newAuthListCmd())
154		cmd.AddCommand(newAuthRevokeCmd())
155		return cmd
156	}
157	
158	// --- status -----------------------------------------------------------------
159	
160	func newAuthStatusCmd() *cobra.Command {
161		var insecureHTTPAuth bool
162		cmd := &cobra.Command{
163			Use:   "status",
164			Short: "Show authentication status",
165			RunE: func(cmd *cobra.Command, _ []string) error {
166				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
167					return err
168				}
169				return runAuthStatus(cmd.Context(), cmd.OutOrStdout(),
170					auth.NewStore(), defaultListTokens, api.AuthBaseURL())
171			},
172		}
173		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
174		return cmd
175	}
176	
177	func defaultListTokens(ctx context.Context) ([]api.Token, error) {
178		token, err := resolveDataAPIToken(ctx)
179		if err != nil {
180			return nil, err
181		}
182		return newAPITokensClient(token).ListTokens(ctx) //nolint:wrapcheck // ListTokens already wraps with action context
183	}
184	
185	func runAuthStatus(ctx context.Context, w io.Writer, store tokenStore, list authTokenLister, baseURL string) error {
186		token, err := store.GetToken(baseURL)
187		if err != nil {
188			return fmt.Errorf("read keychain: %w", err)
189		}
190		if token == "" {
191			fmt.Fprintf(w, "Not logged in to %s\n", baseURL)
192			fmt.Fprintln(w, "Run 'entire login' to authenticate.")
193			return nil
194		}
195	
196		tokens, err := list(ctx)
197		if err != nil {
198			if isKeychainTokenRejected(err) {
199				fmt.Fprintf(w, "Token in keychain for %s is no longer valid.\n", baseURL)
200				fmt.Fprintln(w, "Run 'entire login' to re-authenticate.")
201				return nil
202			}
203			return fmt.Errorf("validate token: %w", err)
204		}
205	
206		fmt.Fprintf(w, "Logged in to %s\n", baseURL)
207		fmt.Fprintln(w, "  Token: stored in OS keychain")
208		fmt.Fprintf(w, "  Active tokens on this account: %d\n", len(tokens))
209		return nil
210	}
211	
212	// --- list -------------------------------------------------------------------
213	
214	func newAuthListCmd() *cobra.Command {
215		var jsonOut bool
216		var insecureHTTPAuth bool
217		cmd := &cobra.Command{
218			Use:   "list",
219			Short: "List active API tokens for the authenticated user",
220			RunE: func(cmd *cobra.Command, _ []string) error {
221				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
222					return err
223				}
224				return runAuthList(cmd.Context(), cmd.OutOrStdout(),
225					auth.NewStore(), defaultListTokens, api.AuthBaseURL(), jsonOut)
226			},
227		}
228		cmd.Flags().BoolVar(&jsonOut, "json", false, "Print tokens as JSON")
229		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
230		return cmd
231	}
232	
233	func runAuthList(ctx context.Context, w io.Writer, store tokenStore, list authTokenLister, baseURL string, jsonOut bool) error {
234		token, err := store.GetToken(baseURL)
235		if err != nil {
236			return fmt.Errorf("read keychain: %w", err)
237		}
238		if token == "" {
239			return fmt.Errorf("not logged in to %s; run 'entire login' first", baseURL)
240		}
241	
242		tokens, err := list(ctx)
243		if err != nil {
244			return err
245		}
246	
247		if jsonOut {
248			enc := json.NewEncoder(w)
249			enc.SetIndent("", "  ")
250			if err := enc.Encode(tokens); err != nil {
251				return fmt.Errorf("encode JSON: %w", err)
252			}
253			return nil
254		}
255	
256		if len(tokens) == 0 {
257			fmt.Fprintln(w, "No active tokens.")
258			return nil
259		}
260	
261		// Deterministic order: most recently used first, then most recently
262		// created, then by id as a final tie-breaker so the output is fully
263		// specified regardless of the server's response order.
264		sort.Slice(tokens, func(i, j int) bool {
265			li := lastUsedSortKey(tokens[i])
266			lj := lastUsedSortKey(tokens[j])
267			if li != lj {
268				return li > lj
269			}
270			if tokens[i].CreatedAt != tokens[j].CreatedAt {
271				return tokens[i].CreatedAt > tokens[j].CreatedAt
272			}
273			return tokens[i].ID < tokens[j].ID
274		})
275	
276		sty := newAuthListStyles(w)
277		renderAuthListTable(w, sty, tokens, time.Now())
278		return nil
279	}
280	
281	// authListStyles holds the lipgloss styles for `entire auth list`. Mirrors the
282	// approach in activity_render.go: keep style construction tied to color
283	// detection, and render plain text when color is disabled.
284	type authListStyles struct {
285		colorEnabled bool
286	
287		header  lipgloss.Style // bold + dim, used for column headers
288		id      lipgloss.Style // yellow accent
289		name    lipgloss.Style // bold
290		value   lipgloss.Style // default fg for scope/dates (no color)
291		dim     lipgloss.Style // "never", "-"
292		warning lipgloss.Style // expires-soon
293		expired lipgloss.Style // already expired
294	}
295	
296	func newAuthListStyles(w io.Writer) authListStyles {
297		useColor := shouldUseColor(w)
298		s := authListStyles{colorEnabled: useColor}
299		if !useColor {
300			return s
301		}
302		s.header = lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Bold(true)
303		s.id = lipgloss.NewStyle().Foreground(lipgloss.Color("3")) // yellow
304		s.name = lipgloss.NewStyle().Bold(true)
305		s.value = lipgloss.NewStyle() // default fg
306		s.dim = lipgloss.NewStyle().Faint(true)
307		s.warning = lipgloss.NewStyle().Foreground(lipgloss.Color("3")) // yellow
308		s.expired = lipgloss.NewStyle().Foreground(lipgloss.Color("1")) // red
309		return s
310	}
311	
312	func (s authListStyles) render(style lipgloss.Style, text string) string {
313		if !s.colorEnabled {
314			return text
315		}
316		return style.Render(text)
317	}
318	
319	// renderAuthListTable prints a styled, column-aligned table of tokens. Column
320	// padding is computed via lipgloss.Width — it strips ANSI escapes, so a styled
321	// cell's visible width matches its plain text. tabwriter can't be used here
322	// once cells contain ANSI codes.
323	func renderAuthListTable(w io.Writer, sty authListStyles, tokens []api.Token, now time.Time) {
324		headerCells := []string{"ID", "NAME", "SCOPE", "CREATED", "LAST USED", "EXPIRES"}
325		header := make([]string, len(headerCells))
326		for i, h := range headerCells {
327			header[i] = sty.render(sty.header, h)
328		}
329	
330		rows := make([][]string, 0, len(tokens))
331		for _, t := range tokens {
332			rows = append(rows, []string{
333				sty.render(sty.id, t.ID),
334				styleName(sty, t.Name),
335				sty.render(sty.value, fallback(t.Scope, placeholderDash)),
336				sty.render(sty.value, formatAuthDate(t.CreatedAt)),
337				styleLastUsed(sty, t.LastUsedAt, now),
338				styleExpires(sty, t.ExpiresAt, now),
339			})
340		}
341	
342		widths := make([]int, len(headerCells))
343		for i, h := range header {
344			widths[i] = lipgloss.Width(h)
345		}
346		for _, row := range rows {
347			for i, c := range row {
348				if cw := lipgloss.Width(c); cw > widths[i] {
349					widths[i] = cw
350				}
351			}
352		}
353	
354		writeRow(w, header, widths)
355		for _, row := range rows {
356			writeRow(w, row, widths)
357		}
358	}
359	
360	func writeRow(w io.Writer, cells []string, widths []int) {
361		for i, c := range cells {
362			fmt.Fprint(w, c)
363			if i < len(cells)-1 {
364				fmt.Fprint(w, strings.Repeat(" ", widths[i]-lipgloss.Width(c)+2))
365			}
366		}
367		fmt.Fprintln(w)
368	}
369	
370	func styleName(sty authListStyles, name string) string {
371		if name == "" {
372			return sty.render(sty.dim, placeholderDash)
373		}
374		return sty.render(sty.name, name)
375	}
376	
377	func styleLastUsed(sty authListStyles, lastUsed *string, now time.Time) string {
378		if lastUsed == nil {
379			return sty.render(sty.dim, lastUsedNever)
380		}
381		return sty.render(sty.value, formatAuthLastUsed(lastUsed, now))
382	}
383	
384	func styleExpires(sty authListStyles, expiresAt string, now time.Time) string {
385		formatted := formatAuthDate(expiresAt)
386		switch classifyExpiresAt(expiresAt, now) {
387		case expiresExpired:
388			return sty.render(sty.expired, formatted)
389		case expiresSoon:
390			return sty.render(sty.warning, formatted)
391		case expiresNormal:
392			return sty.render(sty.value, formatted)
393		}
394		return sty.render(sty.value, formatted)
395	}
396	
397	func lastUsedSortKey(t api.Token) string {
398		if t.LastUsedAt == nil {
399			return ""
400		}
401		return *t.LastUsedAt
402	}
403	
404	// formatAuthDate renders an RFC3339 timestamp as YYYY-MM-DD in local time.
405	func formatAuthDate(s string) string {
406		if s == "" {
407			return placeholderDash
408		}
409		if ts, err := time.Parse(time.RFC3339, s); err == nil {
410			return ts.Local().Format("2006-01-02")
411		}
412		return s
413	}
414	
415	// formatAuthLastUsed renders a relative "last used" timestamp, with "yesterday"
416	// and absolute-date branches that the shared formatRelativeDuration helper
417	// doesn't cover.
418	func formatAuthLastUsed(s *string, now time.Time) string {
419		if s == nil || *s == "" {
420			return lastUsedNever
421		}
422		ts, err := time.Parse(time.RFC3339, *s)
423		if err != nil {
424			return *s
425		}
426		delta := now.Sub(ts)
427		switch {
428		case delta < 0, delta >= 30*24*time.Hour:
429			return ts.Local().Format("2006-01-02")
430		case delta >= 24*time.Hour && delta < 48*time.Hour:
431			return "yesterday"
432		default:
433			return formatRelativeDuration(delta)
434		}
435	}
436	
437	type expiresState int
438	
439	const (
440		expiresNormal expiresState = iota
441		expiresSoon
442		expiresExpired
443	)
444	
445	// classifyExpiresAt classifies an RFC3339 expires-at relative to now. Used to
446	// color the EXPIRES column so tokens worth rotating stand out.
447	func classifyExpiresAt(s string, now time.Time) expiresState {
448		if s == "" {
449			return expiresNormal
450		}
451		ts, err := time.Parse(time.RFC3339, s)
452		if err != nil {
453			return expiresNormal
454		}
455		delta := ts.Sub(now)
456		switch {
457		case delta <= 0:
458			return expiresExpired
459		case delta < 7*24*time.Hour:
460			return expiresSoon
461		default:
462			return expiresNormal
463		}
464	}
465	
466	func fallback(s, alt string) string {
467		if strings.TrimSpace(s) == "" {
468			return alt
469		}
470		return s
471	}
472	
473	// --- revoke -----------------------------------------------------------------
474	
475	func newAuthRevokeCmd() *cobra.Command {
476		var revokeCurrent bool
477		var insecureHTTPAuth bool
478		cmd := &cobra.Command{
479			Use:   "revoke [id]",
480			Short: "Revoke an API token by id",
481			Long:  "Revoke a specific API token. Use --current to revoke the token used by this CLI (equivalent to 'entire logout').",
482			Args:  cobra.MaximumNArgs(1),
483			RunE: func(cmd *cobra.Command, args []string) error {
484				id := ""
485				if len(args) == 1 {
486					id = args[0]
487				}
488				if id == "" && !revokeCurrent {
489					return cmd.Help()
490				}
491				if id != "" && revokeCurrent {
492					return errors.New("cannot use both <id> and --current")
493				}
494				if err := requireSecureBaseURL(insecureHTTPAuth); err != nil {
495					return err
496				}
497				return runAuthRevoke(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(),
498					auth.NewStore(), defaultListTokens, defaultRevokeTokenByID, defaultRevokeCurrentToken,
499					api.AuthBaseURL(), id, revokeCurrent)
500			},
501		}
502		cmd.Flags().BoolVar(&revokeCurrent, "current", false, "Revoke the token used by this CLI and remove the local copy")
503		addInsecureHTTPAuthFlag(cmd, &insecureHTTPAuth)
504		return cmd
505	}
506	
507	func defaultRevokeTokenByID(ctx context.Context, id string) error {
508		token, err := resolveDataAPIToken(ctx)
509		if err != nil {
510			return err
511		}
512		return newAPITokensClient(token).RevokeToken(ctx, id) //nolint:wrapcheck // RevokeToken already wraps with action context
513	}
514	
515	func runAuthRevoke(
516		ctx context.Context,
517		outW, errW io.Writer,
518		store tokenStore,
519		list authTokenLister,
520		revokeByID authTokenRevoker,
521		revokeCurrent revokeCurrentFunc,
522		baseURL, id string,
523		current bool,
524	) error {
525		token, err := store.GetToken(baseURL)
526		if err != nil {
527			return fmt.Errorf("read keychain: %w", err)
528		}
529		if token == "" {
530			return fmt.Errorf("not logged in to %s; run 'entire login' first", baseURL)
531		}
532	
533		if current {
534			// Revoking our own token is just logout — reuse that path so behavior
535			// stays identical (best-effort revoke + local delete).
536			return runLogout(ctx, outW, errW, store, revokeCurrent, baseURL)
537		}
538	
539		if err := revokeByID(ctx, id); err != nil {
540			return err
541		}
542	
543		// The list endpoint requires bearer auth, so a 401 here means the id we
544		// just revoked was the same one this CLI is using — the keychain entry is
545		// now stale and would otherwise produce confusing 401s on every command.
546		if _, listErr := list(ctx); listErr != nil && api.IsHTTPErrorStatus(listErr, http.StatusUnauthorized) {
547			if delErr := store.DeleteToken(baseURL); delErr != nil {
548				return fmt.Errorf("revoked token %s but failed to remove local copy: %w", id, delErr)
549			}
550			fmt.Fprintf(outW, "Revoked token %s (this was your local token; removed from keychain).\n", id)
551			return nil
552		}
553	
554		fmt.Fprintf(outW, "Revoked token %s.\n", id)
555		return nil
556	}
