//go:build authfilestore

// File-backed auth store backend. Compiled only under the `authfilestore`
// build tag, which is enabled by:
//   - the integration test subprocess build (cmd/entire/cli/integration_test/setup_test.go)
//   - test:integration / test:ci tasks (mise.toml) for running this package's
//     tagged tests
//
// Production builds (no tag) do not include this file, so the env var below
// has no effect outside test environments.

package auth

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

// testAuthStoreFileEnv, when set, redirects token storage to a JSON file at
// the given path instead of the OS keyring. Only honored in `authfilestore`
// builds.
const testAuthStoreFileEnv = "ENTIRE_TEST_AUTH_STORE_FILE"

func init() {
	chooseBackend = func() tokenBackend {
		if path := os.Getenv(testAuthStoreFileEnv); path != "" {
			return &fileBackend{path: path}
		}
		return keyringBackend{}
	}
}

type fileBackend struct {
	path string
}

func (b *fileBackend) save(service, key, value string) error {
	tokens, err := b.read()
	if err != nil {
		return err
	}
	svc := tokens[service]
	if svc == nil {
		svc = make(map[string]string)
		tokens[service] = svc
	}
	svc[key] = value
	return b.write(tokens)
}

func (b *fileBackend) get(service, key string) (string, error) {
	tokens, err := b.read()
	if err != nil {
		return "", err
	}
	return tokens[service][key], nil
}

func (b *fileBackend) delete(service, key string) error {
	tokens, err := b.read()
	if err != nil {
		return err
	}
	if svc := tokens[service]; svc != nil {
		delete(svc, key)
		if len(svc) == 0 {
			delete(tokens, service)
		}
	}
	return b.write(tokens)
}

func (b *fileBackend) read() (map[string]map[string]string, error) {
	data, err := os.ReadFile(b.path)
	if errors.Is(err, os.ErrNotExist) {
		return make(map[string]map[string]string), nil
	}
	if err != nil {
		return nil, fmt.Errorf("read test auth store: %w", err)
	}
	if len(data) == 0 {
		return make(map[string]map[string]string), nil
	}

	var tokens map[string]map[string]string
	if err := json.Unmarshal(data, &tokens); err != nil {
		return nil, fmt.Errorf("parse test auth store: %w", err)
	}
	if tokens == nil {
		tokens = make(map[string]map[string]string)
	}
	return tokens, nil
}

func (b *fileBackend) write(tokens map[string]map[string]string) error {
	if err := os.MkdirAll(filepath.Dir(b.path), 0o700); err != nil {
		return fmt.Errorf("create test auth store directory: %w", err)
	}
	data, err := json.Marshal(tokens)
	if err != nil {
		return fmt.Errorf("marshal test auth store: %w", err)
	}
	if err := os.WriteFile(b.path, data, 0o600); err != nil {
		return fmt.Errorf("write test auth store: %w", err)
	}
	// os.WriteFile preserves an existing file's permission bits, so an
	// already-broad file (e.g. 0o644 from an earlier test setup) would
	// keep those bits. Force 0o600 to make the post-condition unconditional.
	if err := os.Chmod(b.path, 0o600); err != nil {
		return fmt.Errorf("restrict test auth store permissions: %w", err)
	}
	return nil
}

// Package logging provides structured logging for the Entire CLI using slog.
//
// Usage:
//
//	// Initialize logger for a session (typically at session start)
//	if err := logging.Init(sessionID); err != nil {
//	    // handle error
//	}
//	defer logging.Close()
//
//	// Add context values
//	ctx = logging.WithSession(ctx, sessionID)
//	ctx = logging.WithToolCall(ctx, toolCallID)
//
//	// Log with context - session/tool IDs extracted automatically
//	logging.Info(ctx, "hook invoked",
//	    slog.String("hook", hookName),
//	    slog.String("branch", branch),
//	)
package logging

import (
	"bufio"
	"context"
	"fmt"
	"io"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/validation"
)

// LogLevelEnvVar is the environment variable that controls log level.
const LogLevelEnvVar = "ENTIRE_LOG_LEVEL"

// LogsDir is the directory where log files are stored (relative to repo root).
const LogsDir = ".entire/logs"

var (
	// logger is the package-level logger instance
	logger *slog.Logger

	// logFile holds the current log file handle for cleanup
	logFile *os.File

	// logBufWriter wraps logFile with buffered I/O for performance
	logBufWriter *bufio.Writer

	// currentSessionID stores the session ID from Init() to include in all logs
	currentSessionID string

	// mu protects logger, logFile, logBufWriter, and currentSessionID
	mu sync.RWMutex

	// logLevelGetter is an optional callback to get log level from settings.
	// Set by SetLogLevelGetter before Init is called.
	logLevelGetter func() string
)

// SetLogLevelGetter sets a callback function to get the log level from settings.
// This allows the logging package to read settings without a circular dependency.
// The callback is only used if ENTIRE_LOG_LEVEL env var is not set.
func SetLogLevelGetter(getter func() string) {
	mu.Lock()
	defer mu.Unlock()
	logLevelGetter = getter
}

// Init initializes the logger for a session, writing JSON logs to
// .entire/logs/entire.log.
//
// If sessionID is non-empty, it is stored as an slog attribute on every log line for filtering.
// If the log file cannot be created, falls back to stderr.
// Log level is controlled by ENTIRE_LOG_LEVEL environment variable.
func Init(ctx context.Context, sessionID string) error {
	// Validate session ID if provided (used only for the slog attribute, not the filename)
	if sessionID != "" {
		if err := validation.ValidateSessionID(sessionID); err != nil {
			return fmt.Errorf("invalid session ID for logging: %w", err)
		}
	}

	mu.Lock()
	defer mu.Unlock()

	// Close any existing log file (flush buffer first)
	if logBufWriter != nil {
		_ = logBufWriter.Flush()
		logBufWriter = nil
	}
	if logFile != nil {
		_ = logFile.Close()
		logFile = nil
	}

